              <template #input="{ model, inputNode }">
                <component :is="inputNode" />
                <span class="uv-check" :class="{ 'is-checked': model.value }" aria-hidden="true">
                  <svg viewBox="0 0 24 24" class="uv-checkmark" focusable="false">
